macro_rules! deps {
    () => {
        Offset!();
        InternalFixed!();
    };
}

macro_rules! Fixed {
    () => {
        deps!();
        # [doc = " Fixed-format item types."] # [doc = ""] # [doc = " They have their own rules of formatting and parsing."] # [doc = " Otherwise noted, they print in the specified cases but parse case-insensitively."] # [non_exhaustive] # [derive (Clone , PartialEq , Eq , Debug , Hash)] # [cfg_attr (feature = "defmt" , derive (defmt :: Format))] pub enum Fixed { # [doc = " Abbreviated month names."] # [doc = ""] # [doc = " Prints a three-letter-long name in the title case, reads the same name in any case."] ShortMonthName , # [doc = " Full month names."] # [doc = ""] # [doc = " Prints a full name in the title case, reads either a short or full name in any case."] LongMonthName , # [doc = " Abbreviated day of the week names."] # [doc = ""] # [doc = " Prints a three-letter-long name in the title case, reads the same name in any case."] ShortWeekdayName , # [doc = " Full day of the week names."] # [doc = ""] # [doc = " Prints a full name in the title case, reads either a short or full name in any case."] LongWeekdayName , # [doc = " AM/PM."] # [doc = ""] # [doc = " Prints in lower case, reads in any case."] LowerAmPm , # [doc = " AM/PM."] # [doc = ""] # [doc = " Prints in upper case, reads in any case."] UpperAmPm , # [doc = " An optional dot plus one or more digits for left-aligned nanoseconds."] # [doc = " May print nothing, 3, 6 or 9 digits according to the available accuracy."] # [doc = " See also [`Numeric::Nanosecond`](./enum.Numeric.html#variant.Nanosecond)."] Nanosecond , # [doc = " Same as [`Nanosecond`](#variant.Nanosecond) but the accuracy is fixed to 3."] Nanosecond3 , # [doc = " Same as [`Nanosecond`](#variant.Nanosecond) but the accuracy is fixed to 6."] Nanosecond6 , # [doc = " Same as [`Nanosecond`](#variant.Nanosecond) but the accuracy is fixed to 9."] Nanosecond9 , # [doc = " Timezone name."] # [doc = ""] # [doc = " It does not support parsing, its use in the parser is an immediate failure."] TimezoneName , # [doc = " Offset from the local time to UTC (`+09:00` or `-04:00` or `+00:00`)."] # [doc = ""] # [doc = " In the parser, the colon can be omitted and/or surrounded with any amount of whitespace."] # [doc = " The offset is limited from `-24:00` to `+24:00`,"] # [doc = " which is the same as [`FixedOffset`](../offset/struct.FixedOffset.html)'s range."] TimezoneOffsetColon , # [doc = " Offset from the local time to UTC with seconds (`+09:00:00` or `-04:00:00` or `+00:00:00`)."] # [doc = ""] # [doc = " In the parser, the colon can be omitted and/or surrounded with any amount of whitespace."] # [doc = " The offset is limited from `-24:00:00` to `+24:00:00`,"] # [doc = " which is the same as [`FixedOffset`](../offset/struct.FixedOffset.html)'s range."] TimezoneOffsetDoubleColon , # [doc = " Offset from the local time to UTC without minutes (`+09` or `-04` or `+00`)."] # [doc = ""] # [doc = " In the parser, the colon can be omitted and/or surrounded with any amount of whitespace."] # [doc = " The offset is limited from `-24` to `+24`,"] # [doc = " which is the same as [`FixedOffset`](../offset/struct.FixedOffset.html)'s range."] TimezoneOffsetTripleColon , # [doc = " Offset from the local time to UTC (`+09:00` or `-04:00` or `Z`)."] # [doc = ""] # [doc = " In the parser, the colon can be omitted and/or surrounded with any amount of whitespace,"] # [doc = " and `Z` can be either in upper case or in lower case."] # [doc = " The offset is limited from `-24:00` to `+24:00`,"] # [doc = " which is the same as [`FixedOffset`](../offset/struct.FixedOffset.html)'s range."] TimezoneOffsetColonZ , # [doc = " Same as [`TimezoneOffsetColon`](#variant.TimezoneOffsetColon) but prints no colon."] # [doc = " Parsing allows an optional colon."] TimezoneOffset , # [doc = " Same as [`TimezoneOffsetColonZ`](#variant.TimezoneOffsetColonZ) but prints no colon."] # [doc = " Parsing allows an optional colon."] TimezoneOffsetZ , # [doc = " RFC 2822 date and time syntax. Commonly used for email and MIME date and time."] RFC2822 , # [doc = " RFC 3339 & ISO 8601 date and time syntax."] RFC3339 , # [doc = " Internal uses only."] # [doc = ""] # [doc = " This item exists so that one can add additional internal-only formatting"] # [doc = " without breaking major compatibility (as enum variants cannot be selectively private)."] Internal (InternalFixed) , }
    };
}

Fixed!();